Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
netfilter: nft_inner: Fix IPv6 inner_thoff desync
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

In nft_inner_parse_l2l3(), when processing inner IPv6 packets,
ipv6_find_hdr() correctly computes the transport header offset
traversing all extension headers, but the result is immediately
overwritten with nhoff + sizeof(_ip6h) (40 bytes), which only
accounts for the IPv6 base header. This creates a desync between
inner_thoff (wrong — points to extension header start) and l4proto
(correct — e.g., IPPROTO_TCP), enabling transport header forgery
and potential firewall bypass. This issue affects stable versions
from Linux 6.2.

For comparison, the normal (non-inner) IPv6 path correctly
preserves ipv6_find_hdr()'s result. Removing the incorrect overwrite
ensures that ipv6_find_hdr()'s calculated transport header offset is
preserved, thereby fixing the desynchronization.

Fixes: 3a07327d10a0 ("netfilter: nft_inner: support for inner tunnel header matching")
Cc: stable@vger.kernel.org
Reported-by: Yizhou Zhao <zhaoyz24@mails.tsinghua.edu.cn>
Reported-by: Yuxiang Yang <yangyx22@mails.tsinghua.edu.cn>
Reported-by: Xuewei Feng <fengxw06@126.com>
Reported-by: Qi Li <qli01@tsinghua.edu.cn>
Reported-by: Ke Xu <xuke@tsinghua.edu.cn>
Assisted-by: GLM:5.1 Z.ai
Signed-off-by: Yizhou Zhao <zhaoyz24@mails.tsinghua.edu.cn>
Reviewed-by: Fernando Fernandez Mancera <fmancera@suse.de>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
In nft_inner_parse_l2l3(), when processing inner IPv6 packets, ipv6_find_hdr() correctly computes the transport header offset (thoff) after traversing all extension headers, but the code immediately overwrites thoff with a fixed value (nhoff + sizeof(_ip6h) = 40 bytes), which only accounts for the IPv6 base header. This desynchronizes inner_thoff (wrong, pointing to extension header start) and l4proto (correct), enabling transport header forgery and potential firewall bypass.

Here is the patch:

 static int nft_inner_parse_l2l3(const struct nft_inner *priv,
 				const struct nft_pktinfo *pkt,
 				struct nft_inner_tun_ctx *ctx, u32 off)
 {
 	__be16 llproto, outer_llproto;
 	u32 nhoff, thoff;

 	if (priv->flags & NFT_INNER_LL) {
 		struct vlan_ethhdr *veth, _veth;
 		struct ethhdr *eth, _eth;
 		u32 hdrsize;

 		eth = skb_header_pointer(pkt->skb, off, sizeof(_eth), &_eth);
 		if (!eth)
 			return -1;

 		switch (eth->h_proto) {
 		case htons(ETH_P_IP):
 		case htons(ETH_P_IPV6):
 			llproto = eth->h_proto;
 			hdrsize = sizeof(_eth);
 			break;
 		case htons(ETH_P_8021Q):
 			veth = skb_header_pointer(pkt->skb, off, sizeof(_veth), &_veth);
 			if (!veth)
 				return -1;

 			outer_llproto = veth->h_vlan_encapsulated_proto;
 			llproto = veth->h_vlan_proto;
 			hdrsize = sizeof(_veth);
 			break;
 		default:
 			return -1;
 		}

 		ctx->inner_lloff = off;
 		ctx->flags |= NFT_PAYLOAD_CTX_INNER_LL;
 		off += hdrsize;
 	} else {
 		struct iphdr *iph;
 		u32 _version;

 		iph = skb_header_pointer(pkt->skb, off, sizeof(_version), &_version);
 		if (!iph)
 			return -1;

 		switch (iph->version) {
 		case 4:
 			llproto = htons(ETH_P_IP);
 			break;
 		case 6:
 			llproto = htons(ETH_P_IPV6);
 			break;
 		default:
 			return -1;
 		}
 	}

 	ctx->llproto = llproto;
 	if (llproto == htons(ETH_P_8021Q))
 		llproto = outer_llproto;

 	nhoff = off;

 	switch (llproto) {
 	case htons(ETH_P_IP): {
 		struct iphdr *iph, _iph;

 		iph = skb_header_pointer(pkt->skb, nhoff, sizeof(_iph), &_iph);
 		if (!iph)
 			return -1;

 		if (iph->ihl < 5 || iph->version != 4)
 			return -1;

 		ctx->inner_nhoff = nhoff;
 		ctx->flags |= NFT_PAYLOAD_CTX_INNER_NH;

 		thoff = nhoff + (iph->ihl * 4);
 		if ((ntohs(iph->frag_off) & IP_OFFSET) == 0) {
 			ctx->flags |= NFT_PAYLOAD_CTX_INNER_TH;
 			ctx->inner_thoff = thoff;
 			ctx->l4proto = iph->protocol;
 		}
 		}
 		break;
 	case htons(ETH_P_IPV6): {
 		struct ipv6hdr *ip6h, _ip6h;
 		int fh_flags = IP6_FH_F_AUTH;
 		unsigned short fragoff;
 		int l4proto;

 		ip6h = skb_header_pointer(pkt->skb, nhoff, sizeof(_ip6h), &_ip6h);
 		if (!ip6h)
 			return -1;

 		if (ip6h->version != 6)
 			return -1;

 		ctx->inner_nhoff = nhoff;
 		ctx->flags |= NFT_PAYLOAD_CTX_INNER_NH;

 		thoff = nhoff;
 		l4proto = ipv6_find_hdr(pkt->skb, &thoff, -1, &fragoff, &fh_flags);
 		if (l4proto < 0 || thoff > U16_MAX)
 			return -1;

 		if (fragoff == 0) {
-			thoff = nhoff + sizeof(_ip6h);
 			ctx->flags |= NFT_PAYLOAD_CTX_INNER_TH;
 			ctx->inner_thoff = thoff;
 			ctx->l4proto = l4proto;
 		}
 		}
 		break;
 	default:
 		return -1;
 	}

 	return 0;
 }



